import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.CQdiwDJy.js";const g=JSON.parse('{"title":"编写技能","description":"","frontmatter":{},"headers":[],"relativePath":"reference/skill-authoring.md","filePath":"reference/skill-authoring.md","lastUpdated":1788601681000}'),l={name:"reference/skill-authoring.md"};function r(s,t,i,c,n,h){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="编写技能" tabindex="-1">编写技能 <a class="header-anchor" href="#编写技能" aria-label="Permalink to &quot;编写技能&quot;">​</a></h1><p>本页面向给 <strong>Tau 仓库本身</strong>写技能的贡献者。给日常使用写技能请看 <a href="/Tau/guide/skills.html">tau skill new</a> 的用户流程。</p><h2 id="skill-md-的三层模型" tabindex="-1">SKILL.md 的三层模型 <a class="header-anchor" href="#skill-md-的三层模型" aria-label="Permalink to &quot;SKILL.md 的三层模型&quot;">​</a></h2><p>Tau 仓库里的 SKILL.md 分三层，放错位置是治理错误：</p><table tabindex="0"><thead><tr><th>层</th><th>位置</th><th>性质</th></tr></thead><tbody><tr><td>L1</td><td><code>.claude/skills/*/SKILL.md</code></td><td>根开发流程技能（build/test/release/docs），跨切面</td></tr><tr><td>L2</td><td><code>packages/&lt;pkg&gt;/SKILL.md</code>、<code>app/&lt;app&gt;/SKILL.md</code></td><td>单包技能，挨着它治理的代码，随包版本化</td></tr><tr><td>L3</td><td><code>packages/skills/bundled/&lt;name&gt;/</code></td><td>随 CLI 发布的<strong>产品内容</strong>（运行时数据），用户通过 <code>tau skill list</code> 看到</td></tr></tbody></table><p>根部的 <code>SKILL.md</code> 是<strong>路由器</strong>：按子系统把人路由到唯一指定的技能文件与规范文档。新增技能时同步更新路由表——每个开发工具有且只有一个指定入口。</p><h2 id="编写规则" tabindex="-1">编写规则 <a class="header-anchor" href="#编写规则" aria-label="Permalink to &quot;编写规则&quot;">​</a></h2><ul><li><strong>frontmatter 必填</strong>：<code>name</code>、<code>description</code>（一句话说清何时触发）、<code>risk</code>。</li><li><strong>内容结构</strong>：先一句话定位（这是什么、不是什么），再操作路径，最后常见陷阱。宁可短而准，不要长而全。</li><li><strong>声明式命令</strong>：L3 技能的命令是声明（展开成意图），不是脚本；风险声明走与内置工具相同的门。</li><li><strong>spec 引用</strong>：技能是索引与工作流，规范性细节放 <code>AGENTS/&lt;topic&gt;.md</code> 并链接过去——同一规则只在一处定义。</li></ul><h2 id="用户技能-vs-仓库技能" tabindex="-1">用户技能 vs 仓库技能 <a class="header-anchor" href="#用户技能-vs-仓库技能" aria-label="Permalink to &quot;用户技能 vs 仓库技能&quot;">​</a></h2><ul><li>给<strong>用户</strong>的能力 → L3 <code>packages/skills/bundled/</code>，或 <code>$TAU_HOME/skills/</code> / 工作区 <code>./skills/</code>（不进仓库）。</li><li>给<strong>开发 AI agent</strong> 的工作流 → L1 或 L2，进仓库，随代码一起评审。</li></ul><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><p>新技能 PR 必须包含：frontmatter 完整、根路由表（若新增根技能）、治理表行（<code>AGENTS/architecture.md</code>，若新增位置）、以及 <code>tau skill list</code> 的输出验证。</p>',12)])])}const p=e(l,[["render",r]]);export{g as __pageData,p as default};
